sys_security_acl.script:
answer = false;

var EXCLUDED_GROUP = '5ee74940b70022108d4406dd1e11a918';

var agentId = current.getValue('agent');
var loggedInUserId = gs.getUserID();

if (agentId == loggedInUserId) {
    answer = true;
}
if (agentId) {
    var groups = gs.getUser().getMyGroups();

    if (groups && groups.length > 0) {
        var grUser = new GlideRecord('sys_user_grmember');
        grUser.addQuery('user', agentId);
        grUser.addQuery('group', 'IN', groups.join(','));
        grUser.addQuery('group', '!=', EXCLUDED_GROUP);
        grUser.setLimit(1);
        grUser.query();

        if (grUser.hasNext()) {
            answer = true;
        }
    }
}
